function AnalyticsPage(){const [range,setRange]=useState('7d'),[data,setData]=useState<any>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{setLoading(true);api(`/analytics?range=${range}`).then(setData).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[range]);return <><PageHeading eyebrow="YOUR FOCUS, OVER TIME" title="Progress without pressure." desc="Your completed sessions, recorded as you go. Every minute comes from your actual focus history." action={<div className="range-switch">{[['today','Today'],['7d','7 days'],['30d','30 days']].map(([v,l])=><button key={v} className={range===v?'selected':''} onClick={()=>setRange(v)}>{l}</button>)}</div>}/>{error&&<div className="error-inline">{error}</div>}{loading?<Loading/>:data&&<><div className="stats-grid analytics-stats"><StatCard label="Focus time" value={`${data.totalMinutes}m`} detail="In selected period" icon={<Clock3/>}/><StatCard label="Sessions" value={data.sessions} detail="Completed in selected period" icon={<CheckCircle2/>} accent="mint"/><StatCard label="Average session" value={`${data.averageMinutes}m`} detail="Across completed sessions" icon={<Activity/>} accent="blue"/></div><section className="panel chart-panel"><div className="panel-heading"><div><h3>Daily focus time</h3><p>Completed minutes per day</p></div><span className="chart-legend"><i/> Focus minutes</span></div>{data.daily.every((d:any)=>d.minutes===0)?<Empty title="Your chart is ready for you" text="Complete a focus session to see your real progress here." action={<Link className="btn btn-secondary" to="/focus">Start focusing</Link>}/>:<div className="chart-wrap"><ResponsiveChart data={data.daily}/></div>}</section><section className="panel analytics-note"><div className="feature-icon"><Activity/></div><div><h3>Consistency over intensity.</h3><p>These insights are based only on completed sessions saved to your account. Choose a small, repeatable focus ritual and let the habit build naturally.</p></div></section></>}</>}
function ResponsiveChart({data}:{data:{date:string;minutes:number}[]}){const {ResponsiveContainer,BarChart,Bar,XAxis,YAxis,Tooltip,CartesianGrid}=requireRecharts();return <ResponsiveContainer width="100%" height="100%"><BarChart data={data} margin={{top:12,right:8,left:-15,bottom:0}}><CartesianGrid strokeDasharray="3 3" stroke="var(--chart-grid)"/><XAxis dataKey="date" tickFormatter={(d:string)=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'})} stroke="var(--muted)" fontSize={11} tickLine={false} axisLine={false}/><YAxis stroke="var(--muted)" fontSize={11} tickLine={false} axisLine={false}/><Tooltip contentStyle={{background:'var(--panel)',border:'1px solid var(--line)',borderRadius:12,color:'var(--text)'}} labelFormatter={(d:string)=>new Date(d+'T12:00:00').toLocaleDateString()} formatter={(v:number)=>[`${v} minutes`,'Focus time']}/><Bar dataKey="minutes" fill="#8b7cff" radius={[5,5,0,0]} maxBarSize={42}/></BarChart></ResponsiveContainer>}
