function ProfilePage(){const {user,refresh}=useAuth();const [name,setName]=useState(user?.name||''),[email,setEmail]=useState(user?.email||''),[current,setCurrent]=useState(''),[next,setNext]=useState(''),[confirm,setConfirm]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function profile(e:FormEvent){e.preventDefault();setBusy(true);setError('');setMessage('');try{await api('/profile',{method:'PUT',body:JSON.stringify({name,email})});await refresh();setMessage('Profile updated successfully.');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}async function password(e:FormEvent){e.preventDefault();setError('');setMessage('');if(next!==confirm){setError('New passwords do not match.');return;}setBusy(true);try{await api('/profile/password',{method:'PUT',body:JSON.stringify({currentPassword:current,newPassword:next})});setCurrent('');setNext('');setConfirm('');setMessage('Password changed successfully.');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <><PageHeading eyebrow="YOUR ACCOUNT" title="Your profile." desc="Manage your personal details and keep your account secure."/><div className="profile-layout">{error&&<div className="error-inline">{error}</div>}{message&&<div className="success-inline">{message}</div>}<section className="panel profile-card"><div className="profile-avatar">{user?.name?.charAt(0).toUpperCase()}</div><div><h3>{user?.name}</h3><p>{user?.email}</p><span className="verified-label"><CheckCircle2 size={13}/> Personal workspace</span></div></section><section className="panel settings-form-panel"><div className="panel-heading"><div><h3>Personal information</h3><p>Update the details attached to your account.</p></div></div><form className="form-stack" onSubmit={profile}><label>Full name<input value={name} onChange={e=>setName(e.target.value)} required minLength={2}/></label><label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><button className="btn btn-primary" disabled={busy}><Save size={16}/>{busy?'Saving…':'Save profile'}</button></form></section><section className="panel settings-form-panel"><div className="panel-heading"><div><h3>Change password</h3><p>Use a new password you haven't used before.</p></div></div><form className="form-stack" onSubmit={password}><label>Current password<input type="password" value={current} onChange={e=>setCurrent(e.target.value)} required/></label><div className="form-two"><label>New password<input type="password" value={next} onChange={e=>setNext(e.target.value)} minLength={8} required/></label><label>Confirm new password<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} minLength={8} required/></label></div><button className="btn btn-primary" disabled={busy}><Save size={16}/>{busy?'Updating…':'Update password'}</button></form></section></div></>}
function SettingsPage({onTheme}:{onTheme:(t:'dark'|'light')=>void}){const [settings,setSettings]=useState<Preference>({theme:'dark',defaultTimer:25,notifications:true,soundEnabled:true}),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');useEffect(()=>{api<Preference>('/settings').then(s=>{setSettings(s);onTheme(s.theme)}).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[]);function update<K extends keyof Preference>(k:K,v:Preference[K]){setSettings(s=>({...s,[k]:v}));}async function save(){setBusy(true);setMessage('');setError('');try{const r=await api<Preference>('/settings',{method:'PUT',body:JSON.stringify(settings)});setSettings(r);onTheme(r.theme);setMessage('Settings saved.');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}if(loading)return <Loading/>;return <><PageHeading eyebrow="MAKE IT FEEL LIKE YOURS" title="Settings." desc="Small preferences that make your focus ritual feel natural."/><div className="settings-layout">{error&&<div className="error-inline">{error}</div>}{message&&<div className="success-inline">{message}</div>}<section className="panel settings-section"><div className="settings-section-icon"><Sun/></div><div className="settings-section-body"><h3>Appearance</h3><p>Choose the atmosphere for your workspace.</p><div className="theme-options"><button className={settings.theme==='dark'?'theme-choice selected':''} onClick={()=>{update('theme','dark');onTheme('dark')}}><span className="theme-preview dark-preview"><Moon/></span><b>Dark</b>{settings.theme==='dark'&&<Check size={15}/>}</button><button className={settings.theme==='light'?'theme-choice selected':''} onClick={()=>{update('theme','light');onTheme('light')}}><span className="theme-preview light-preview"><Sun/></span><b>Light</b>{settings.theme==='light'&&<Check size={15}/>}</button></div></div></section><section className="panel settings-section"><div className="settings-section-icon"><Clock3/></div><div className="settings-section-body"><h3>Focus timer</h3><p>Your preferred duration for a new focus session.</p><div className="setting-inline"><span>Default duration</span><select value={settings.defaultTimer} onChange={e=>update('defaultTimer',Number(e.target.value))}>{[15,25,35,45,50,60,90,120].map(n=><option key={n} value={n}>{n} minutes</option>)}</select></div></div></section><section className="panel settings-section"><div className="settings-section-icon"><Activity/></div><div className="settings-section-body"><h3>Preferences</h3><p>Choose which little helpers are enabled.</p><Toggle label="Session completion notifications" desc="Show a completion message when your timer ends." value={settings.notifications} onChange={v=>update('notifications',v)}/><Toggle label="Sound playback" desc="Allow ambient sounds to play in your workspace." value={settings.soundEnabled} onChange={v=>update('soundEnabled',v)}/></div></section><div className="settings-save"><button className="btn btn-primary" onClick={save} disabled={busy}><Save size={16}/>{busy?'Saving…':'Save preferences'}</button></div></div></>}
function Toggle({label,desc,value,onChange}:{label:string;desc:string;value:boolean;onChange:(v:boolean)=>void}){return <div className="toggle-row"><div><b>{label}</b><small>{desc}</small></div><button type="button" role="switch" aria-checked={value} className={`toggle ${value?'on':''}`} onClick={()=>onChange(!value)}><span/></button></div>}
export default App;
